/* ================= MODERATOR ================= */
function pinScreen(){return `<section class="card stack narrow"><div class="eyebrow">Moderators only</div><h2>Enter the moderator PIN</h2><p class="small muted m0">${esc(D.meta?D.meta.name:"")}</p><input type="password" id="pin" inputmode="numeric" autocomplete="off" data-draft="pin" value="${esc(dv("pin",""))}"><button class="btn primary" data-act="pin">Open the console</button><a class="small muted" href="${esc(eventURL(EV))}">I'm a guest</a></section>`}
function moderator(){
 const tab=(k,l)=>`<button data-act="mtab" data-k="${k}" aria-pressed="${L.mtab===k}">${l}</button>`;
 const body=({live:mLive,moments:mMoments,teams:mTeams,scores:mScores,content:mContent,custom:mCustom,event:mEvent,memories:mMemories}[L.mtab]||mLive)();
 const pr=D.meta&&D.meta.practice?`<div class="banner soft"><span><b>Practice run</b> with pretend guests. Open a <a href="${esc(eventURL(EV))}" target="_blank" rel="noopener">guest view</a> or the <a href="${esc(eventURL(EV,"screen"))}" target="_blank" rel="noopener">big screen</a> to see what they see.</span><button class="btn sm" data-act="endPractice">End practice</button></div>`:"";
 return `${status()}${pr}<div class="console"><nav class="side">${tab("live","Live")}${tab("moments","Moments")}${tab("teams","Teams")}${tab("scores","Scores")}${tab("content","Content")}${tab("custom","Custom games")}${tab("event","Event")}${tab("memories","Memories")}</nav><div class="stack mw0">${body}</div></div>`}

/* ---- Live ---- */
function mLive(){
 const live=st().live;
 const cgs=Object.keys(cgAll()).sort((a,b)=>(cgAll()[a].t||0)-(cgAll()[b].t||0)).map(id=>({id:"c:"+id,name:cgAll()[id].name,note:"Custom game"}));
 const rows=enabledGames().concat(cgs).map((g,k)=>`<div class="gamerow ${live===g.id?"on":""}"><span class="gnum">${k+1}</span><div><b>${g.name}</b><div class="small muted">${g.note}</div></div>${live===g.id?`<button class="btn sm" data-act="endGame">End</button>`:`<button class="btn sm primary" data-act="goLive" data-id="${g.id}">Go live</button>`}</div>`).join("");
 return `${checklist()}${st().moment?`<div class="banner"><span>On the TV: <b>${esc((momentsList().find(x=>x.id===st().moment.id)||{name:"a moment"}).name)}</b>. Games still run underneath.</span><button class="btn sm" data-act="moStop">Take it off</button></div>`:""}<section class="card stack"><div class="row between"><h2>Tonight's games</h2><span class="small muted">${ids().length} guests joined · going live runs a 5-second countdown on every phone</span></div><div class="gamelist">${rows}</div></section>${tools()}${reviewQueue()}
 <section class="card stack"><h3>Send an announcement</h3><div class="row"><input type="text" id="annText" class="grow" data-draft="ann" aria-label="Announcement for the big screen" value="${esc(dv("ann",""))}" placeholder="Bingo starts in 5 minutes!"><button class="btn primary" data-act="announce">Send to every phone</button></div></section>`}
function paceBar(done,total,since,label){const pct=total?Math.round(100*done/total):0;const secs=since?Math.round((now()-since)/1000):0;
 let nudge="";if(total&&pct>=80)nudge=`<div class="nudge">Most guests have ${label}. Move on when you're ready.</div>`;else if(since&&secs>75)nudge=`<div class="nudge">It's been over a minute. Consider moving on.</div>`;
 return `<div class="stack tight"><div class="row between small"><span><b class="num">${done}</b> of ${total} ${label}</span><span class="num muted">${pct}%${since?` · ${Math.floor(secs/60)}:${String(secs%60).padStart(2,"0")}`:""}</span></div><div class="bar"><i style="width:${pct}%"></i></div>${nudge}</div>`}
function tools(){
 const id=st().live;if(liveCg())return cgLiveTools(liveCg());
 if(id==="bingo"){const called=st().called||[],last=called[called.length-1],round=st().bingoRound||1;
  let board='<div class="called">';for(let n=1;n<=75;n++)board+=`<span class="${called.includes(n)?"on":""}">${n}</span>`;board+="</div>";
  const cl=(D.claims||{})[round]||{};const pend=Object.keys(cl).filter(p=>!cl[p].ok).length;
  const claims=Object.keys(cl).map(pid=>{const ok=hasBingo(cardFor(pid,round),n=>called.includes(n));return `<div class="row between"><span>${av(pid,22)} <b>${esc(P(pid).name)}</b> called bingo ${ok?'<span class="pill ok">Card checks out</span>':'<span class="pill no">Not a bingo yet</span>'}</span>${cl[pid].ok?'<span class="pill ok">Confirmed</span>':`<span class="row"><button class="btn sm gold" data-act="bConfirm" data-id="${pid}" ${ok?"":"disabled"}>Confirm</button><button class="btn sm" data-act="bDeny" data-id="${pid}">Deny</button></span>`}</div>`}).join("");
  return `<section class="card stack"><div class="row between"><h3>Bingo caller · round ${round}</h3><div class="row">${last?`<div class="ball sm">${letter(last)}${last}</div>`:""}<button class="btn primary" data-act="callNext">Call next number</button><button class="btn" data-act="newBingo">New round</button></div></div>${pend?`<div class="nudge">${pend} bingo call${pend>1?"s":""} waiting for you.</div>`:""}<div class="tscroll">${board}</div>${claims?`<h3>Bingo calls</h3>${claims}`:'<p class="small muted m0">Bingo calls from guests show up here, already checked against their cards.</p>'}</section>`}
 if(id==="trivia"){const list=TRV(),qi=Math.min(st().tvQ||0,list.length-1),it=list[qi]||{o:[],a:0,q:""},v=D.tv[qi]||{},phase=st().tvPhase||"vote";
  const pods=st().pods||{};const expected=Object.keys(pods).filter(i=>D.players[i]).length;const voted=Object.keys(v).filter(k=>k!=="_res"&&pods[k]).length;
  const pk=[...new Set(Object.values(pods))].sort();const res=v._res||{};
  return `<section class="card stack"><div class="row between"><div><h3>Trivia · question ${qi+1} of ${list.length}</h3><p class="m0 mt4">${esc(it.q)}</p></div>${it.hard?'<span class="pill no">Hard</span>':""}</div>
  <div class="key">${it.o.map((o,k)=>`<span class="${k===it.a?"right":""}"><b>${"ABCD"[k]}</b> ${esc(o)}${k===it.a?" ✓":""}</span>`).join("")}</div>
  ${phase==="vote"?paceBar(voted,expected,st().tvAt,"voted"):""}
  <div class="row">${phase==="vote"?`<button class="btn primary" data-act="tvClose">Close voting</button>`:phase==="revote"?`<span class="pill warn">Tied pods revoting · <span class="num" data-timer="${st().tvRevoteEnd}">${fmtLeft(st().tvRevoteEnd)}</span></span><button class="btn primary" data-act="tvFinish">Finish revote now</button>`:`<button class="btn primary" data-act="tvNext" ${qi>=list.length-1?"disabled":""}>Send next question</button>`}<button class="btn" data-act="podsReset">Reset pods</button>${hint("pods")}</div>
  <div class="row small">${pk.map(p=>`<span class="pill ${p[0].toLowerCase()}">Pod ${p}: ${res[p]?(res[p].tie?"tied":res[p].correct?"right":"wrong"):"—"}</span>`).join("")}</div>${phase==="done"&&qi>=list.length-1?'<div class="nudge">That was the last question. End trivia when you\'re ready.</div>':""}</section>`}
 if(id==="sup"){const list=SUPS(),qi=Math.min(st().supQ||0,list.length-1),v=D.sup[qi]||{},pair=st().supPair||["",""];const voted=Object.keys(v).filter(k=>k!=="_res").length;
  return `<section class="card stack"><div class="row between"><h3>Superlatives · question ${qi+1} of ${list.length}</h3></div><p class="m0">Who is most likely to ${esc(supQ(list[qi]||{q:""}))}</p>
  <div class="row"><span class="small">Pair up front:</span>${[0,1].map(s=>`<select data-act="pairPick" data-s="${s}"><option value="">Pick a guest</option>${ids().map(i=>`<option value="${i}" ${pair[s]===i?"selected":""}>${esc(P(i).name)}</option>`).join("")}</select>`).join("")}</div>
  ${v._res?"":paceBar(voted,ids().length,st().supAt,"voted")}
  <div class="row">${v._res?`<button class="btn primary" data-act="supNext" ${qi>=list.length-1?"disabled":""}>Next question</button>`:`<button class="btn primary" data-act="supReveal">Reveal results</button>`}</div>${v._res?supResult(v._res):'<span class="small muted">The app works out each team\'s agreement percentage for you.</span>'}</section>`}
 if(id==="longword"){const end=st().lwEnd,over=end&&now()>end;const words=Object.keys(D.lwAll||{}).filter(k=>(D.lwAll[k]||{}).word&&D.players[k]).length;
  return `<section class="card stack"><div class="row between"><div><h3>Long Word Wins timer</h3><span class="small muted">${end?(over?"Time's up":`<span class="num" data-timer="${end}">${fmtLeft(end)}</span> left`):"Not started"}</span></div><div class="row"><input type="number" id="lwMins" min="5" max="45" data-draft="lwMins" value="${esc(dv("lwMins",st().lwMins||15))}"><span class="small">min</span><button class="btn primary" data-act="lwStart">${end?"Restart":"Start timer"}</button></div></div>
  ${end?paceBar(words,ids().length,null,"played a word"):""}${over?'<div class="nudge">Time\'s up. The big screen is showing the longest words. Move on when you\'re ready.</div>':""}</section>`}
 if(id==="split"){return `<section class="card stack"><h3>Team Splitter</h3><p class="small muted m0">Guests see their team and can suggest team names. Set the final names in the Teams tab.</p><button class="btn as" data-act="mtab" data-k="teams">Open Teams</button></section>`}
 if(id==="crossword"){const G=CWG();const all=D.huntAll;return `<section class="card stack"><h3>Crossword</h3><p class="small muted m0">${G.placed.length} words in the puzzle. Guests score as they solve.</p></section>`}
 return ""}
function reviewQueue(){
 const list=Object.keys(D.photos||{}).map(k=>Object.assign({key:k},D.photos[k])).filter(x=>!x.checked).sort((a,b)=>a.t-b.t);const items=HUNTS();
 return `<section class="card stack"><div class="row between"><h3>Scavenger Hunt photos</h3><span class="small muted">${list.length} to check · points are given right away</span></div>${list.length>10?'<div class="nudge">The photo queue is filling up. Your assistant can help from their own phone.</div>':""}${list.length?list.slice(0,12).map(x=>`<div class="item"><div class="thumb">${x.img?`<img src="${x.img}" alt="">`:"?"}</div><div><b>${esc(P(x.who).name)}</b><div class="small muted">Says it's the ${esc(((items[x.k]||{}).n||"item").toLowerCase())}</div></div><div class="row"><button class="btn sm gold" data-act="pOk" data-key="${x.key}">Looks good</button><button class="btn sm" data-act="pNo" data-key="${x.key}">Remove</button></div></div>`).join(""):`<p class="small muted m0">All caught up.</p>`}</section>`}

/* ---- Dealing teams: random, by seating (chart or join answer), or by hand ---- */
const sitKey=v=>{const x=normName(v);const d=x.match(/\d+/);return d?"table "+(+d[0]):x};
function proxPlaces(){const out={},tbs=PLN().tables||{},have=Object.values(PLN().seats||{}).filter(x=>x&&tbs[x.tb]),byFull={},byFirst={};
 have.forEach(x=>{const nn=normName(x.n),lbl=tbs[x.tb].name||"Table";byFull[nn]=lbl;const f=nn.split(" ")[0];(byFirst[f]=byFirst[f]||[]).push({nn,lbl})});
 ids().forEach(id=>{const p=P(id),nn=normName(p.name);let lbl="";
  if(byFull[nn])lbl=byFull[nn];else{const parts=nn.split(" "),li=(parts[1]||"")[0];const c=(byFirst[parts[0]]||[]).filter(x=>{const q=x.nn.split(" ");return !li||(q[q.length-1]||"")[0]===li});
   if(c.length&&new Set(c.map(x=>x.lbl)).size===1)lbl=c[0].lbl}
  if(!lbl&&p.sit)lbl=sitKey(p.sit);
  if(lbl)out[id]=lbl});return out}
const chartOn=()=>{const tbs=PLN().tables||{};return Object.values(PLN().seats||{}).some(x=>x&&tbs[x.tb])};
function shuffled(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function dealGroups(mode,n){const ks=teamKeys(n),list=ids(),out={},cnt={};ks.forEach(k=>cnt[k]=0);
 if(mode==="prox"){const pl=proxPlaces();
  const near=list.filter(i=>pl[i]).sort((a,b)=>String(pl[a]).localeCompare(String(pl[b]),undefined,{numeric:true})||(P(a).t||0)-(P(b).t||0)),rest=list.filter(i=>!pl[i]);
  near.forEach((id,k)=>{const tm=ks[Math.min(ks.length-1,Math.floor(k*ks.length/near.length))];out[id]=tm;cnt[tm]++});
  shuffled(rest).forEach(id=>{const tm=ks.reduce((a,b)=>cnt[b]<cnt[a]?b:a);out[id]=tm;cnt[tm]++})}
 else shuffled(list).forEach((id,k)=>out[id]=ks[k%ks.length]);
 return out}
/* ---- Teams ---- */
function mTeams(){
 const n=nTeams(),W=grpWord(),Wc=W[0].toUpperCase()+W.slice(1),mode=st().split||"seasons",isNew=NEWSPLIT(mode),ks=teamKeys();
 const col=tm=>{const m=members(tm);const sg=(D.sugg||{})[tm]||{};const sl=Object.keys(sg).map(k=>({k,name:sg[k].name,v:Object.keys(sg[k].v||{}).length})).sort((a,b)=>b.v-a.v).slice(0,5);const cap=captainOf(tm);
  return `<section class="card stack"><div class="row between"><h3>${esc(teamName(tm))}</h3><span class="pill ${tm.toLowerCase()}">${m.length} players</span></div>
  <div class="small">${cap?`★ Captain: <b>${esc(P(cap).name)}</b>`:'<span class="muted">No captain yet. Tap "Make captain" next to a name.</span>'}</div>
  <div class="stack tight"><span class="small">${Wc} name</span><div class="row"><input type="text" class="grow" data-draft="tn${tm}" value="${esc(dv("tn"+tm,(st().teamNames||{})[tm]||""))}" placeholder="${esc(teamName(tm))}"><button class="btn sm primary" data-act="setTeamName" data-t="${tm}">Set</button></div>
  ${sl.length?`<div class="row small">${sl.map(s=>`<button class="btn xs" data-act="useSugg" data-t="${tm}" data-k="${s.k}">${esc(s.name)} · ${s.v}</button>`).join("")}</div>`:'<span class="small muted">Guest suggestions show up here during Team Splitter.</span>'}</div>
  <div class="stack tight">${m.map(i=>`<div class="row between small"><span>${cap===i?"★ ":""}${av(i,22)} ${esc(P(i).name)} <span class="muted">${MON[P(i).m-1]} ${P(i).d}</span>${P(i).sit&&mode==="prox"?` <span class="muted">· ${esc(P(i).sit)}</span>`:""}${podOf(i)?` <span class="muted">· pod ${podOf(i)}</span>`:""}${!isNew&&(st().override||{})[i]?' <span class="pill warn">moved</span>':""}${P(i).bot?' <span class="pill">bot</span>':""}</span><span class="row"><button class="btn sm ${cap===i?"gold":""}" data-act="captain" data-t="${tm}" data-id="${i}">${cap===i?"Captain":"Make captain"}</button>${n===2?`<button class="btn sm" data-act="move" data-id="${i}">Move to ${tm==="A"?"B":"A"}</button>`:`<select class="sm" data-act="moveTo" data-id="${i}" aria-label="Move ${esc(P(i).name)}">${ks.map(k=>`<option value="${k}" ${k===tm?"selected":""}>${esc(teamName(k))}</option>`).join("")}</select>`}<button class="btn sm" data-act="kick" data-id="${i}">Remove</button></span></div>`).join("")||'<span class="small muted">Nobody yet</span>'}</div></section>`};
 const pl=mode==="prox"?proxPlaces():{},placed=Object.keys(pl).length,total=ids().length;
 const desc={random:"Everyone is dealt to a "+W+" at random, evenly. Tap Deal again to reshuffle, then move anyone by hand.",
  prox:(chartOn()?"Guests who sit near each other end up together, following your seating chart in the Plan tab.":"There is no seating chart yet, so guests are asked where they sit when they join (a table number or an area), and neighbors are grouped.")+` ${placed} of ${total} guests have a seat so far; the rest fill the smallest ${W}s.`,
  hand:"You place everyone yourself. Start from the current split and use the menu next to each name to move people."}[mode];
 return `<section class="card stack"><h2>How many ${W}s? ${hint("split")}</h2><div class="seg wrap" role="group" aria-label="Number of teams">${[2,3,4,5,6,7,8,9,10,12].map(k=>`<button data-act="teamN" data-v="${k}" aria-pressed="${n===k}">${k}</button>`).join("")}</div>
 <p class="small muted m0">Up to seven are called teams. Eight or more are called pods. You have ${n} ${W}s.</p></section>
 <section class="card stack"><h2>How should the room split?</h2><div class="seg wrap" role="group" aria-label="Team split">${n===2?`<button data-act="split" data-v="seasons" aria-pressed="${mode==="seasons"}">Seasons</button><button data-act="split" data-v="oddeven" aria-pressed="${mode==="oddeven"}">Odd &amp; even birthdays</button>`:""}<button data-act="splitMode" data-v="random" aria-pressed="${mode==="random"}">Random</button><button data-act="splitMode" data-v="prox" aria-pressed="${mode==="prox"}">By seating</button><button data-act="splitMode" data-v="hand" aria-pressed="${mode==="hand"}">By hand</button></div>
 ${mode==="seasons"?`<div class="row small"><span>Seasons go by ${hint("season")}</span><div class="seg" role="group" aria-label="Season dates"><button data-act="seasonMode" data-v="month" aria-pressed="${(st().seasonMode||"month")==="month"}">Month (Dec–May)</button><button data-act="seasonMode" data-v="dates" aria-pressed="${st().seasonMode==="dates"}">Start dates (Dec 21–Jun 20)</button></div></div>`:""}
 <p class="small muted m0">${isNew?desc:(mode==="seasons"?((st().seasonMode||"month")==="dates"?"Birthdays from December 21 through June 20 (winter and spring) form one team. June 21 through December 20 (summer and fall) form the other.":"Birthdays in December through May (winter and spring) form one team. June through November (summer and fall) form the other."):"Odd days of the month (1st, 3rd, 5th…) form one team, even days the other.")} Once the first game after the split starts, latecomers join the smaller ${W}.</p>
 <div class="row">${isNew?`<button class="btn primary" data-act="reDeal">${mode==="prox"?"Regroup by seating":"Deal again"}</button>`:""}<button class="btn" data-act="capRandom">Pick captains at random</button></div>${st().locked?'<span class="pill warn as">Teams are locked in</span>':""}</section><div class="grid2">${ks.map(col).join("")}</div>`}

/* ---- Scores ---- */
function mScores(){const order=ranked(),tbk=(tiedTop().length>1?tiedTop():teamKeys()),tie=C().tie||{},tb=st().tiebreak;
 return `${teamBar()}
 <section class="card stack"><h3>Finish the night</h3><div class="row"><button class="btn gold" data-act="winner">${st().showWinner?"Hide winner":"Show winner on big screen"}</button><button class="btn primary" data-act="endNight">${st().ended?"Reopen the games":"End the night and send recaps"}</button></div><p class="small muted m0">Ending the night shows the winner with an entrance on the big screen and gives every guest their personal recap.</p></section>
 <section class="card stack"><h3>Tiebreaker ${hint("tie")}</h3><p class="m0">${esc(tie.q||"")} <span class="pill ok">Answer: ${esc(tie.a)}</span></p>${winnerKey()?"":'<div class="nudge">The '+grpWord()+'s are tied. Run the tiebreaker.</div>'}
 ${tb?`<div class="row">${tbk.map(k=>`<label class="row small">${esc(teamName(k))} guess <input type="number" data-draft="tb${k}" value="${esc(dv("tb"+k,""))}"></label>`).join("")}<button class="btn primary" data-act="tbReveal">Reveal closest</button><button class="btn" data-act="tbOff">Hide</button></div>${tb.result?`<p class="m0"><b>${esc(tb.result)}</b></p>`:""}`:`<button class="btn as" data-act="tbOn">Show tiebreaker on the big screen</button>`}</section>
 <section class="card row between"><span class="small">${grpWord()==="pod"?"Pod":"Team"} points</span><span class="row">${teamKeys().map(tm=>`<span class="pill ${tm.toLowerCase()}">${esc(teamName(tm))}</span><button class="btn sm" data-act="tadj" data-t="${tm}" data-d="-1">−</button><button class="btn sm" data-act="tadj" data-t="${tm}" data-d="1">+</button>`).join("")}</span></section>
 <section class="card stack"><h3>Prizes</h3><div class="row small"><span class="pill warn">Raffle</span><span>Draw a random winner from the guests who joined.</span><button class="btn sm" data-act="raffle">Draw</button></div>${st().raffle?`<p class="m0">Raffle winner: <b>${esc(st().raffle)}</b></p>`:""}</section>
 <section class="card tscroll"><table><thead><tr><th>#</th><th>Guest</th><th>Team</th><th class="tr">Points</th><th class="tr">Fix</th></tr></thead><tbody>${order.map((i,k)=>`<tr><td class="num">${k+1}</td><td>${av(i,22)} ${esc(P(i).name)}</td><td><span class="pill ${teamOf(i).toLowerCase()}">${esc(teamName(teamOf(i)))}</span></td><td class="num tr">${score(i)}</td><td class="tr nw"><button class="btn sm" data-act="adj" data-id="${i}" data-d="-1" aria-label="Take a point from ${esc(P(i).name)}">−</button> <button class="btn sm" data-act="adj" data-id="${i}" data-d="1" aria-label="Give a point to ${esc(P(i).name)}">+</button></td></tr>`).join("")}</tbody></table></section>`}

/* ---- Content: lists, answer key, editor, AI helper ---- */
const KINDS={trivia:"Trivia",hunt:"Scavenger Hunt",cw:"Crossword",sups:"Superlatives",tie:"Tiebreaker"};
function cleanLine(s){return s.replace(/^\s*(?:\d+[.)]|[-*•])\s*/,"").trim()}
function toText(kind){const c=C();
 if(kind==="trivia")return TRV().map(x=>`${x.q} | ${x.o.join(" | ")} | ${"ABCD"[x.a]||"A"}${x.hard?" | hard":""}`+(x.es&&x.es.q?`\nes: ${x.es.q} | ${arr(x.es.o).join(" | ")}`:"")).join("\n");
 if(kind==="hunt")return HUNTS().map(x=>`${x.n} | ${x.h}`+(x.es&&x.es.n?`\nes: ${x.es.n} | ${x.es.h||""}`:"")).join("\n");
 if(kind==="cw")return CWW().map(x=>`${x.w} | ${x.c}`+(x.es?`\nes: ${x.es}`:"")).join("\n");
 if(kind==="sups")return SUPS().map(x=>x.q+(x.es?`\nes: ${x.es}`:"")).join("\n");
 if(kind==="tie"){const x=c.tie||{};return `${x.q||""} | ${x.a==null?"":x.a}`+(x.es?`\nes: ${x.es}`:"")}}
function parseKind(kind,text){const out=[],errs=[];const lines=String(text||"").split(/\r?\n/);
 lines.forEach((raw,n)=>{const line=cleanLine(raw);if(!line||/^```/.test(line))return;
  const isEs=/^es\s*:/i.test(line);const body=line.replace(/^es\s*:\s*/i,"");const parts=body.split("|").map(s=>s.trim());
  if(isEs){const last=out[out.length-1];if(!last){errs.push(n+1);return}
   if(kind==="trivia"){if(parts.length>=5)last.es={q:parts[0],o:parts.slice(1,5)};else errs.push(n+1)}
   else if(kind==="hunt")last.es={n:parts[0],h:parts[1]||""};
   else last.es=body.trim();return}
  if(kind==="trivia"){if(parts.length<6){errs.push(n+1);return}const a="ABCD".indexOf(parts[5].toUpperCase().replace(/[^A-D]/g,"")[0]);if(a<0){errs.push(n+1);return}
   out.push({q:parts[0],o:parts.slice(1,5),a,hard:/hard/i.test(parts.slice(6).join(" "))||undefined})}
  else if(kind==="hunt"){if(parts.length<2||!parts[0]){errs.push(n+1);return}out.push({n:parts[0],h:parts[1]})}
  else if(kind==="cw"){const w=(parts[0]||"").toUpperCase().replace(/[^A-Z]/g,"");if(w.length<2||!parts[1]){errs.push(n+1);return}out.push({w,c:parts[1]})}
  else if(kind==="sups"){let q=body.replace(/^who('s| is)? (most )?likely to\s*/i,"").trim();if(!q){errs.push(n+1);return}if(!/[?]$/.test(q))q+="?";out.push({q:q.charAt(0).toUpperCase()+q.slice(1)})}
  else if(kind==="tie"){const a=parseFloat((parts[1]||"").replace(/[^0-9.\-]/g,""));if(!parts[0]||isNaN(a)){errs.push(n+1);return}out.push({q:parts[0],a})}});
 out.forEach(o=>{Object.keys(o).forEach(k=>o[k]===undefined&&delete o[k])});return {items:out,errs}}
function promptFor(kind){const c=C();const n=+dv("aiN_"+kind,{trivia:10,hunt:8,cw:12,sups:8,tie:1}[kind]);const es=dv("aiEs_"+kind,"1")==="1";
 const theme=((c.themeDesc||c.title||"a party")+(c.honorees?` honoring ${c.honorees}`:"")).replace(/[.\s]+$/,"");
 const head=`I'm hosting ${theme}. I'm running party games on guests' phones.`;
 const fmt="Reply with only the list, one item per line, in exactly this format, with no numbering, headings or extra text:";
 if(kind==="trivia")return `${head} Write ${n} multiple-choice trivia questions that fit this theme. Make most of them fun and easy, and about ${Math.max(1,Math.round(n*.3))} hard ones that most guests will have to guess. Each question has exactly 4 answer choices written in the same style (for example, all exact numbers or all short phrases), with only one correct answer.\n\n${fmt}\nQuestion | choice A | choice B | choice C | choice D | letter of the correct choice\nAdd " | hard" to the end of each hard question's line.${es?`\nRight after each question line, add a Spanish translation line in this format:\nes: pregunta | opción A | opción B | opción C | opción D`:""}\n\nExample:\nHow many bones is a newborn born with? | 100 | 206 | 300 | 500 | C${es?"\nes: ¿Con cuántos huesos nace un recién nacido? | 100 | 206 | 300 | 500":""}`;
 if(kind==="hunt")return `${head} Suggest ${n} scavenger hunt items the host can hide around the venue. They should fit the theme, be small, easy to buy or find, and easy to photograph. For each item, write a short playful hint that describes it without naming it.\n\n${fmt}\nItem name | hint${es?`\nRight after each line, add a Spanish line in this format:\nes: nombre | pista`:""}\n\nExample:\nRubber duck | I float through every bath time.${es?"\nes: Patito de goma | Floto en cada hora del baño.":""}`;
 if(kind==="cw")return `${head} Suggest ${n} English words for a crossword that fit this theme. Each word must be a single word with letters only (no spaces or hyphens), 3 to 9 letters long. Choose words that share common letters so they interlock well. For each word, write a short, friendly clue.\n\n${fmt}\nWORD | clue${es?`\nRight after each line, add the clue in Spanish (the answer stays in English) in this format:\nes: pista`:""}\n\nExample:\nCRADLE | A bed that rocks${es?"\nes: Una cama que se mece":""}`;
 if(kind==="sups")return `${head} Guests vote on "Who is most likely to…" questions, choosing between ${SUPOPT().join(" and ")}. Write ${n} fun, kind questions that fit this theme. Write only the ending of each question, starting with a verb and ending with a question mark.\n\n${fmt}\nending of the question?${es?`\nRight after each line, add the Spanish ending in this format (it follows "¿Quién tiene más probabilidades de"):\nes: final de la pregunta?`:""}\n\nExample:\nCry the hardest when the baby is born?${es?"\nes: llorar más fuerte cuando nazca el bebé?":""}`;
 if(kind==="tie")return `${head} Write one tiebreaker question for the end of the night that has a single number as its answer, so the team whose guess is closest wins. It should fit the theme and be hard to know exactly.\n\n${fmt}\nQuestion | number${es?`\nThen add a Spanish line:\nes: pregunta`:""}\n\nExample:\nHow many diapers does a baby use in its first year? | 2500${es?"\nes: ¿Cuántos pañales usa un bebé en su primer año?":""}`}
function keyView(kind){
 if(kind==="trivia")return `<ol class="keylist">${TRV().map(x=>`<li><b>${esc(x.q)}</b>${x.hard?' <span class="pill no">Hard</span>':""}<div class="key">${x.o.map((o,k)=>`<span class="${k===x.a?"right":""}"><b>${"ABCD"[k]}</b> ${esc(o)}${k===x.a?" ✓":""}</span>`).join("")}</div>${x.es&&x.es.q?`<div class="small muted">ES: ${esc(x.es.q)}</div>`:""}</li>`).join("")}</ol>`;
 if(kind==="hunt")return `<ol class="keylist">${HUNTS().map(x=>`<li><b>${esc(x.n)}</b> <span class="muted">· ${esc(x.h)}</span></li>`).join("")}</ol>`;
 if(kind==="cw"){const G=CWG();return `<p class="small m0">${G.placed.length} of ${CWW().length} words fit in the puzzle.${G.unplaced.length?` <span class="bad">Not used: ${esc(G.unplaced.join(", "))}. Try words that share more letters.</span>`:""}</p><ol class="keylist">${CWW().map(x=>`<li><b>${esc(x.w)}</b> <span class="muted">· ${esc(x.c)}</span></li>`).join("")}</ol>`}
 if(kind==="sups")return `<p class="small m0">Answer choices: <b>${esc(SUPOPT().join(" · "))}</b> (change them in Event)</p><ol class="keylist">${SUPS().map(x=>`<li>Who is most likely to ${esc(supQ(x))}</li>`).join("")}</ol>`;
 if(kind==="tie"){const x=C().tie||{};return `<p class="m0"><b>${esc(x.q||"")}</b> <span class="pill ok">Answer: ${esc(x.a)}</span></p>`}}
function mContent(){markSetup("content");
 const k=L.ctab,mode=(L.cmode||{})[k]||"view";const sub=Object.keys(KINDS).map(x=>`<button data-act="ctab" data-k="${x}" aria-pressed="${k===x}">${KINDS[x]}</button>`).join("");
 const count={trivia:TRV().length,hunt:HUNTS().length,cw:CWW().length,sups:SUPS().length,tie:1}[k];
 let body;
 if(mode==="edit")body=`<p class="small muted m0">${formatHelp(k)}</p><textarea id="ed_${k}" data-draft="ed_${k}" rows="14" spellcheck="false">${esc(dv("ed_"+k,toText(k)))}</textarea><div class="row"><button class="btn primary" data-act="saveList" data-k="${k}">Save</button><button class="btn" data-act="cmode" data-k="${k}" data-m="view">Cancel</button></div>`;
 else if(mode==="ai"){const pr=promptFor(k);const pasted=dv("ai_"+k,"");const parsed=pasted?parseKind(k,pasted):null;
  body=`<ol class="steps"><li><div class="row">${k==="tie"?"":`<label class="row small">How many <input type="number" min="1" max="30" data-draft="aiN_${k}" value="${esc(dv("aiN_"+k,{trivia:10,hunt:8,cw:12,sups:8,tie:1}[k]))}" data-act="aiRefresh"></label>`}<label class="row small">Include Spanish <select data-draft="aiEs_${k}" data-act="aiRefresh"><option value="1" ${dv("aiEs_"+k,"1")==="1"?"selected":""}>Yes</option><option value="0" ${dv("aiEs_"+k,"1")==="0"?"selected":""}>No</option></select></label></div></li>
  <li>Copy this request and paste it into Claude.<textarea id="aiPrompt" rows="8" readonly>${esc(pr)}</textarea><div class="row"><button class="btn primary" data-act="copyPrompt">Copy request</button><a class="btn" href="https://claude.ai/new" target="_blank" rel="noopener">Open Claude</a></div></li>
  <li>Paste Claude's answer here.<textarea id="ai_${k}" data-draft="ai_${k}" rows="8" spellcheck="false" placeholder="Paste the answer…">${esc(pasted)}</textarea>${parsed?`<p class="small m0">${parsed.items.length} item${parsed.items.length===1?"":"s"} ready${parsed.errs.length?` · <span class="bad">couldn't read line${parsed.errs.length>1?"s":""} ${parsed.errs.join(", ")}</span>`:""}</p>`:""}
  <div class="row"><button class="btn primary" data-act="aiApply" data-k="${k}" data-how="replace" ${parsed&&parsed.items.length?"":"disabled"}>Replace the list</button>${k!=="tie"?`<button class="btn" data-act="aiApply" data-k="${k}" data-how="add" ${parsed&&parsed.items.length?"":"disabled"}>Add to the list</button>`:""}<button class="btn" data-act="cmode" data-k="${k}" data-m="view">Cancel</button></div></li></ol>`}
 else body=keyView(k);
 return `<section class="card stack"><div class="row between"><h2>Game content</h2><span class="small muted">Theme: ${esc(C().themeDesc||C().title||"")}</span></div><div class="seg wrapseg" role="group" aria-label="Content type">${sub}</div></section>
 <section class="card stack"><div class="row between"><h3>${KINDS[k]}${k==="tie"?"":` · ${count}`}${k==="trivia"?" · answer key":""}</h3><div class="row">${mode==="view"?`<button class="btn sm" data-act="cmode" data-k="${k}" data-m="edit">Edit list</button><button class="btn sm primary" data-act="cmode" data-k="${k}" data-m="ai">Get ideas with AI</button>`:""}</div></div>${body}</section>`}
function formatHelp(k){return {trivia:"One question per line: Question | A | B | C | D | correct letter. Add | hard for hard ones. Optional Spanish line below it: es: pregunta | a | b | c | d",
 hunt:"One item per line: Item | hint. Optional Spanish line below it: es: objeto | pista",cw:"One word per line: WORD | clue. Optional Spanish clue below it: es: pista",
 sups:"One question ending per line, for example: Spoil the baby rotten? Optional Spanish line below it: es: consentir demasiado al bebé?",tie:"Question | number answer. Optional Spanish line below it: es: pregunta"}[k]}

/* ---- Event ---- */
function mEvent(){const c=C(),m=D.meta||{};const cs=c.colors||{};const g=c.games||ALL_GAMES_ON;
 const PV=[["hunt","Scavenger Hunt","per item"],["crossword","Crossword","per word"],["trivia","Trivia","per right answer"],["bingo","Bingo","per bingo"],["sup","Superlatives","per round"],["longword","Long Word Wins","per letter"]];
 const themes=D.themes||{};const tl=Object.keys(themes).sort((a,b)=>(themes[b].t||0)-(themes[a].t||0));
 const fld=(k,label,val,ph)=>`<label class="stack tight"><span class="small">${label}</span><input type="text" data-draft="ev_${k}" value="${esc(dv("ev_"+k,val||""))}" placeholder="${esc(ph||"")}"></label>`;
 const typ=evType();
 return `<section class="card stack"><h2>Event type ${hint("eventType")}</h2><p class="m0"><b>${esc(typeDef().label)}</b>. The type is set when an event is created, so changing your plans never overwrites this event.</p><a class="btn sm as" href="${esc(baseURL())}#new" target="_blank" rel="noopener">Start a new event instead</a></section>
 <section class="card stack"><h2>Event details</h2><div class="grid2 g8">${fld("title","Title on every screen",c.title)}${fld("tagline","Line under the title",c.tagline)}${fld("honorees","Guests of honor",c.honorees,"Raveen & Stafford Jr.")}${fld("date","Date",c.date,"2027-01-02")}</div>
 ${fld("themeDesc","Theme description (the AI helper uses this)",c.themeDesc,"a baby shower with an enchanted garden theme")}${fld("supOpts","Superlatives answer choices, separated by commas",SUPOPT().join(", "))}
 <button class="btn primary as" data-act="saveDetails">Save details</button></section>
 <section class="card stack"><h2>Look</h2><div class="row top g16">${(L.drafts.ts_image||c.image)?`<img class="invite" src="${L.drafts.ts_image||c.image}" alt="Event image">`:'<div class="invite ph0">No image</div>'}<div class="stack grow mw200"><p class="small muted m0">Upload an invitation or flyer. We pull up to 8 colors from it, then you can set every part of the page.</p><div class="row"><label class="btn upl">Upload an image<input type="file" accept="image/*" data-act="tsImg" aria-label="Event image"></label>${c.image?'<button class="btn sm" data-act="removeImg">Remove image</button>':""}</div></div></div>${themeStudio("ts_",false)}</section>
 <section class="card stack"><h2>Games tonight</h2><div class="grid2 g8">${GAMES.map(x=>`<button class="toggle" data-act="toggleGame" data-k="${x.id}" aria-pressed="${g[x.id]!==false}"><span>${x.name}</span><i></i></button>`).join("")}</div></section>
 <section class="card stack"><h2>Point values ${hint("points")}</h2><div class="grid2 g8">${PV.map(([k,n,u])=>`<label class="row between pvrow"><span>${n} <span class="muted small">${u}</span></span><input type="number" min="0" max="20" value="${pv(k)}" data-act="pv" data-k="${k}"></label>`).join("")}</div></section>
 <section class="card stack"><h2>Saved themes ${hint("themes")}</h2><p class="small muted m0">A theme keeps the title, colors, image and all game content. Save this event as a theme, or load one to switch everything at once.</p>
 <div class="row"><input type="text" class="grow" data-draft="themeName" value="${esc(dv("themeName",c.title||""))}" placeholder="Theme name"><button class="btn primary" data-act="saveTheme">Save as theme</button></div>
 <div class="stack tight">${tl.length?tl.map(id=>`<div class="row between"><span><b>${esc(themes[id].name)}</b> <span class="small muted">${esc((themes[id].content||{}).themeDesc||"")}</span></span>${L.confirm==="theme:"+id?`<span class="row"><span class="small">Replace this event's content?</span><button class="btn sm gold" data-act="useTheme" data-id="${id}">Yes, switch</button><button class="btn sm" data-act="cancelConfirm">No</button></span>`:`<button class="btn sm" data-act="askTheme" data-id="${id}">Use this theme</button>`}</div>`).join(""):'<span class="small muted">No saved themes yet.</span>'}</div></section>
 <section class="card stack"><h2>Links</h2><div class="row top g16"><div class="qrbox" data-qr="${esc(eventURL(EV))}" data-size="150"></div><div class="stack grow mw200 tight">
 <span class="small"><b>Guests:</b> <span class="brk">${esc(eventURL(EV))}</span></span><span class="small"><b>Big screen:</b> <span class="brk">${esc(eventURL(EV,"screen"))}</span></span><span class="small"><b>Moderators:</b> <span class="brk">${esc(eventURL(EV,"moderator"))}</span></span><span class="small"><b>Shared album:</b> <span class="brk">${esc(eventURL(EV,"album"))}</span></span>
 <a class="btn as" href="${esc(eventURL(EV,"print"))}" target="_blank" rel="noopener">Open the printable kit</a></div></div></section>
 ${m.practice?"":`<section class="card stack"><h2>Rehearsal ${hint("practice")}</h2><p class="small muted m0">Practice the whole night with 16 pretend guests who vote, find items and call bingo. It runs in a separate practice event, so tonight's scores stay clean.</p><button class="btn primary as" data-act="startPractice">Start a practice run</button></section>`}
 <section class="card stack"><h2>Photo cleanup ${hint("retention")}</h2><div class="row"><span class="small">Delete photos after</span><input type="number" min="0" max="365" data-draft="ret" value="${esc(dv("ret",C().retentionDays!=null?C().retentionDays:60))}"><span class="small">days</span><button class="btn sm" data-act="saveRetention">Save</button></div><p class="small muted m0">Cleanup runs each time a host or moderator console opens. 0 keeps photos.</p></section>
 <section class="card stack"><h2>Moderators ${hint("pin")}</h2>${L.isAdmin||L.isOwner?modsPanel(EV,D.mods,D.meta):`<p class="small m0">You're signed in as <b>${esc(L.modName||"a moderator")}</b>. Only the person who created this event or the administrator can add or remove moderators.</p>`}</section>
 <section class="card stack"><h2>Start fresh</h2>${L.isAdmin?freshPanel(EV):'<p class="small muted m0">Only the administrator can clear the event. Ask them to sign in with the host PIN.</p>'}</section>`}

