function hostView(){
 if(!L.loaded)return loadingView();
 if(!L.hostOK)return `<section class="card stack narrow"><div class="eyebrow">Administrator</div><h2>Enter the host PIN</h2><p class="small muted m0">The host PIN is the administrator PIN. It opens every event.</p><input type="password" inputmode="numeric" id="hpin" data-draft="hpin" value="${esc(dv("hpin",""))}"><button class="btn primary" data-act="hostPin">Open</button></section>`;
 const tab=(k,l)=>`<button data-act="hostTab" data-k="${k}" aria-pressed="${(L.hostTab||"events")===k}">${l}</button>`;
 const body={support:supportBody,sales:salesBody,resources:resourcesBody,marketing:marketingBody,agents:agentsBody,usage:usageBody,events:hEvents,invites:hInvites,planners:hPlanners,leads:hLeads,archives:hArchives,themes:hThemes,library:hLibrary,settings:hSettings}[L.hostTab||"events"]();
 return `<div class="console"><nav class="side">${tab("events","Events")}${tab("support","Support"+(tkNewCount()?` <span class="pill warn">${tkNewCount()}</span>`:""))}${tab("sales","Sales"+(slDue()?` <span class="pill warn">${slDue()}</span>`:""))}${tab("resources","Resources")}${tab("marketing","Marketing")}${tab("agents","Agents")}${tab("usage","Usage")}${tab("invites","Invite codes")}${tab("planners","Planners")}${tab("leads","Contacts"+(Object.keys(D.leads||{}).length?` <span class="pill gold">${Object.keys(D.leads).length}</span>`:""))}${tab("archives","Archives")}${tab("themes","Themes")}${tab("library","Game inventory")}${tab("settings","Host settings")}</nav><div class="stack mw0">${body}</div></div>`}
function hEvents(){const ev=D.events||{},def=D.admin.defaultEvent;const keys=Object.keys(ev).sort((a,b)=>(ev[b].created||0)-(ev[a].created||0));const th=D.themes||{};
 return `<section class="card stack"><h2>Your events</h2>${keys.length?keys.map(k=>`<div class="gamerow evrow"><span class="gnum">${def===k?"★":""}</span><div class="mw0"><b>${esc(ev[k].name||k)}</b> ${ev[k].practice?'<span class="pill warn">practice</span>':""}<div class="small muted">Code ${esc(k)}${def===k?" · opens from the main link":""}</div></div>
 <div class="row">${L.confirm==="del:"+k?`<span class="small">Delete everything?</span><button class="btn sm gold" data-act="delEvent" data-k="${k}">Delete</button><button class="btn sm" data-act="cancelConfirm">Keep</button>`:`<button class="btn sm primary" data-act="openMod" data-k="${k}">Console</button><a class="btn sm" href="${esc(eventURL(k))}" target="_blank" rel="noopener">Guest view</a><a class="btn sm" href="${esc(eventURL(k,"screen"))}" target="_blank" rel="noopener">Big screen</a>${def===k?"":`<button class="btn sm" data-act="setMain" data-k="${k}">Make main</button>`}<button class="btn sm" data-act="askDel" data-k="${k}">Delete</button>`}</div></div>`).join(""):'<p class="small muted m0">No events yet.</p>'}</section>
 <section class="card stack"><h2>New event</h2><div class="grid2 g8"><label class="stack tight"><span class="small">Event name</span><input type="text" data-draft="ne_name" value="${esc(dv("ne_name",""))}" placeholder="Aunt Lisa's 60th birthday"></label>
 <label class="stack tight"><span class="small">Event code (letters and numbers)</span><input type="text" data-draft="ne_code" value="${esc(dv("ne_code",""))}" placeholder="Leave blank to make one" autocapitalize="characters"></label>
 <label class="stack tight"><span class="small">Moderator PIN for this event</span><input type="text" inputmode="numeric" data-draft="ne_pin" value="${esc(dv("ne_pin",""))}" placeholder="4 or more digits"></label>
 <label class="stack tight"><span class="small">Event type ${hint("eventType")}</span><select data-draft="ne_type">${Object.keys(EVENT_TYPES).map(k=>`<option value="${k}" ${dv("ne_type","baby")===k?"selected":""}>${EVENT_TYPES[k].label}</option>`).join("")}</select></label>
 <label class="stack tight"><span class="small">Start from</span><select data-draft="ne_from"><option value="starter">Starter games for this event type</option><option value="blank" ${dv("ne_from","")==="blank"?"selected":""}>Blank party template</option>${Object.keys(th).map(id=>`<option value="t:${id}" ${dv("ne_from","")==="t:"+id?"selected":""}>Theme: ${esc(th[id].name)}</option>`).join("")}</select></label></div>
 <button class="btn primary as" data-act="newEvent">Create event</button><p class="small muted m0">Give the PIN to whoever runs the event, like your cousin for her clients. It only opens that event.</p></section>`}
function hThemes(){const th=D.themes||{};const keys=Object.keys(th).sort((a,b)=>(th[b].t||0)-(th[a].t||0));
 return `<section class="card stack"><h2>Saved themes</h2><p class="small muted m0">Save a theme from any event's Event tab. Each one keeps its title, colors, image and game content.</p>${keys.length?keys.map(id=>`<div class="gamerow evrow"><span class="gnum"></span><div class="mw0"><input type="text" data-draft="tn_${id}" value="${esc(dv("tn_"+id,th[id].name))}" aria-label="Theme name"><div class="small muted">${esc((th[id].content||{}).themeDesc||"")}</div></div><div class="row"><button class="btn sm" data-act="renameTheme" data-id="${id}">Rename</button><button class="btn sm" data-act="dupTheme" data-id="${id}">Duplicate</button>${L.confirm==="dt:"+id?`<button class="btn sm gold" data-act="delTheme" data-id="${id}">Delete</button><button class="btn sm" data-act="cancelConfirm">Keep</button>`:`<button class="btn sm" data-act="askDelTheme" data-id="${id}">Delete</button>`}</div></div>`).join(""):'<p class="small muted m0">No saved themes yet.</p>'}</section>`}
function hSettings(){return `<section class="card stack"><h2>Host PIN</h2><p class="small muted m0">${D.admin.pinHash?"You've set your own host PIN. It opens every event's console as the administrator.":"You haven't set a host PIN yet, so administrator sign-in at events is turned off. Set one with at least 6 digits."}</p><div class="row"><input type="password" inputmode="numeric" data-draft="newHost" value="${esc(dv("newHost",""))}" placeholder="New host PIN"><button class="btn primary" data-act="changeHostPin">Save</button></div></section>
 <section class="card stack"><h2>Main link</h2><p class="small muted m0">Guests who open <span class="brk">${esc(baseURL())}</span> without a code go to your main event: <b>${esc(D.admin.defaultEvent||"none")}</b>. Change it from the Events tab.</p></section>
 <section class="card stack"><h2>Fine print</h2><p class="small muted m0">Your Terms and Privacy Policy show this name and contact. Use your name or business and an email address guests can write to.</p><div class="grid2 g8"><label class="stack tight"><span class="small">Name or business</span><input type="text" data-draft="lg_name" value="${esc(dv("lg_name",D.admin.legalName||""))}" placeholder="Host Mode LLC"></label><label class="stack tight"><span class="small">Contact</span><input type="text" data-draft="lg_contact" value="${esc(dv("lg_contact",D.admin.contact||""))}" placeholder="email@example.com"></label></div><button class="btn as" data-act="saveLegal">Save</button>${legalFoot()}</section>
 <section class="card stack"><h2>Sign out</h2><button class="btn as" data-act="hostOut">Sign out of the admin console</button></section>`}

/* ================= BIG SCREEN ================= */
function bigscreen(){
 const s=st(),order=ranked().slice(0,10),g=s.live?gameById(s.live):null;let stage;
 const opts=SUPOPT();
 if(s.showWinner||s.ended){const w=winnerKey();stage=`<div class="eyebrow">Tonight's champions</div><div class="winner">${w?esc(teamName(w)):"It's a tie!"}</div><p class="muted">${w?`${D.team[w]} points`:"Time for the tiebreaker question."}</p>`}
 else if(s.tiebreak){const tie=C().tie||{};stage=`<div class="eyebrow">Tiebreaker</div><h2 class="big">${esc(tie.q||"")}</h2><p class="muted">Each team agrees on one number. Closest guess wins.</p>${s.tiebreak.result?`<div class="winner sm">${esc(s.tiebreak.result)}</div>`:""}`}
 else if(!g){const al=D.album||{},ks=Object.keys(al).slice(-8).reverse();stage=`${C().image?`<img class="ev-art big" src="${C().image}" alt="">`:""}<div class="winner">Welcome!</div><p class="muted">Scan to join the games</p><div class="qrbox asc" data-qr="${esc(eventURL(EV))}" data-size="190"></div>${ks.length?`<div class="strip">${ks.map(k=>`<img src="${al[k].thumb}" alt="">`).join("")}</div>`:""}`}
 else if(g&&g.custom)stage=`<div class="cgph" data-slot="s"></div>`;
 else if(s.live==="bingo"){const c=s.called||[],last=c[c.length-1];stage=`<div class="eyebrow">Bingo · last call</div><div class="huge pop" >${last?letter(last)+"-"+last:"Get ready"}</div><p class="muted">${c.slice(-6,-1).reverse().map(n=>letter(n)+"-"+n).join(" · ")}</p>`}
 else if(s.live==="trivia"){const list=TRV(),qi=Math.min(s.tvQ||0,list.length-1),it=list[qi]||{o:[],q:"",a:0};const shown=s.tvPhase==="done";
  stage=`<div class="eyebrow">Trivia · question ${qi+1} of ${list.length}</div><h2 class="big">${esc(it.q)}</h2><div class="grid2 tl">${it.o.map((x,k)=>`<div class="card ${shown&&k===it.a?"choice right":""}"><b class="gnum il">${"ABCD"[k]}</b> ${esc(x)}</div>`).join("")}</div>${s.tvPhase==="revote"?`<p class="banner jc">Tied pods are revoting · <span class="num" data-timer="${s.tvRevoteEnd}">${fmtLeft(s.tvRevoteEnd)}</span></p>`:""}`}
 else if(s.live==="longword"){const over=s.lwEnd&&now()>s.lwEnd;
  if(over){const ws=Object.keys(D.lwAll||{}).filter(k=>(D.lwAll[k]||{}).word&&D.players[k]).map(k=>({k,w:D.lwAll[k].word})).sort((a,b)=>b.w.length-a.w.length).slice(0,6);
   stage=`<div class="eyebrow">Long Word Wins · longest words</div>${ws.length?ws.map((x,i)=>`<div class="row jc wordrow">${av(x.k,34)} <b>${esc(P(x.k).name)}</b> <span class="tiles">${x.w.split("").map(l=>`<span class="tile sm">${l}</span>`).join("")}</span></div>`).join(""):'<p class="muted">No words played yet.</p>'}`}
  else stage=`<div class="eyebrow">Long Word Wins</div><div class="huge num" ${s.lwEnd?`data-timer="${s.lwEnd}"`:""}>${s.lwEnd?fmtLeft(s.lwEnd):(s.lwMins||15)+":00"}</div><p class="muted">Go meet people and collect their letters.</p>`}
 else if(s.live==="sup"){const list=SUPS(),qi=Math.min(s.supQ||0,list.length-1),res=(D.sup[qi]||{})._res;stage=`<div class="eyebrow">Superlatives</div><h2 class="big">Who is most likely to ${esc(supQ(list[qi]||{q:""}))}</h2><div class="row jc">${opts.map(o=>`<span class="pill big">${esc(o)}</span>`).join("")}</div><p class="muted">Up front: ${(s.supPair||[]).filter(i=>D.players[i]).map(i=>esc(P(i).name)).join(" &amp; ")||"to be picked"}</p>${res?supResult(res):""}`}
 else if(s.live==="split")stage=`<div class="eyebrow">Find your team</div><div class="grid2"><div><div class="winner sm">${esc(teamName("A"))}</div><p class="muted">${members("A").length} players</p></div><div><div class="winner sm">${esc(teamName("B"))}</div><p class="muted">${members("B").length} players</p></div></div>`;
 else stage=`<div class="eyebrow">Now playing</div><div class="winner">${esc(g.name)}</div><p class="muted">Play on your phone.</p>`;
 return `${s.announce&&now()-s.announce.t<120000?`<div class="banner mb12"><span>${esc(s.announce.text)}</span></div>`:""}<div class="tv"><section class="stage">${stage}</section><div class="stack">${teamBar()}<section class="card"><h3>Leaderboard</h3><table><tbody>${order.map((i,k)=>`<tr><td class="num">${k+1}</td><td>${av(i,26)} ${esc(P(i).name)}</td><td class="num tr">${score(i)}</td></tr>`).join("")}</tbody></table></section></div></div>`}

/* ================= SHARED GALLERY ================= */
function galleryView(){return `<section class="card stack"><div class="eyebrow">${esc(C().tagline||"")}</div><h2>${t("Shared album")}</h2><p class="small muted m0">${t("Everyone's photos from tonight, live.")}</p></section><section class="card">${albumGrid(false)}</section>`}

/* ================= PRINTABLE KIT ================= */
function printView(){markSetup("share");const c=C(),url=eventURL(EV),sel=L.printSel;const w=D.wishes||{};
 const box=(k,l)=>`<label class="row small"><input type="checkbox" data-act="printSel" data-k="${k}" ${sel[k]?"checked":""}> ${l}</label>`;
 const hunt=HUNTS(),list=TRV();
 return `<section class="card stack noprint"><h2>Printable kit</h2><div class="row">${box("door","Door sign")}${box("table","Table cards")}${box("hints","Hunt hint cards")}${box("key","Host answer key")}${box("cheat","Night-of cheat sheet")}${box("wishes","Wishes keepsake")}</div><div class="row"><button class="btn primary" data-act="print">Print</button><a class="btn" href="${esc(eventURL(EV,"moderator"))}">Back to the console</a></div><p class="small muted m0">Tip: in the print dialog, turn on background graphics for full color.</p></section>
 ${sel.cheat?cheatSheet():""}
 ${sel.door?`<div class="sheetp door"><div class="eyebrow">${esc(c.tagline||"")}</div><div class="winner">${esc(c.title||"Party Games")}</div><p class="lead">Scan to join the games</p><div class="qrbox" data-qr="${esc(url)}" data-size="320"></div><p class="small brk">${esc(url)}</p></div>`:""}
 ${sel.table?`<div class="sheetp cards2">${[0,1].map(()=>`<div class="tcard"><div class="winner sm">${esc(c.title||"")}</div><div class="qrbox" data-qr="${esc(url)}" data-size="150"></div><ol class="small"><li>Scan the code with your phone camera.</li><li>Enter your name and birthday.</li><li>Your phone joins every game as it starts.</li></ol></div>`).join("")}</div>`:""}
 ${sel.hints&&hunt.length?`<div class="sheetp"><h2>Scavenger Hunt hints</h2><div class="hintgrid">${hunt.map((x,k)=>`<div class="hcard"><div class="eyebrow">Mystery item ${k+1}</div><p>${esc(x.h)}</p>${x.es&&x.es.h?`<p class="small muted">${esc(x.es.h)}</p>`:""}</div>`).join("")}</div></div>`:""}
 ${sel.key?`<div class="sheetp"><h2>Host answer key</h2><h3>Trivia</h3><ol class="keylist">${list.map(x=>`<li>${esc(x.q)} <b>${"ABCD"[x.a]}. ${esc(x.o[x.a]||"")}</b></li>`).join("")}</ol><h3>Scavenger Hunt</h3><ol class="keylist">${hunt.map(x=>`<li>${esc(x.h)} <b>${esc(x.n)}</b></li>`).join("")}</ol><h3>Tiebreaker</h3><p>${esc((c.tie||{}).q||"")} <b>${esc((c.tie||{}).a)}</b></p></div>`:""}
 ${sel.wishes?`<div class="sheetp"><div class="tc"><div class="eyebrow">${esc(c.tagline||"")}</div><div class="winner">Wishes for ${esc(c.honorees||"you")}</div></div><div class="wishgrid">${Object.keys(w).map(k=>`<div class="wish"><p class="m0">${esc(w[k].text)}</p><p class="small muted m0">${esc(w[k].name||"")}</p></div>`).join("")||'<p class="muted">No wishes yet.</p>'}</div></div>`:""}`}

